  'faqs-heading' => 'अक्सर पूछे जाने वाले प्रश्नों',
  'faq1-question' => 'क्या मैं पासवर्ड से सुरक्षित पीडीएफ को विभाजित कर सकता हूँ?',
  'faq1-answer' => 'सही पासवर्ड के बिना नहीं. जब आप फ़ाइल अपलोड करेंगे या खोलेंगे तो अधिकांश टूल आपको इसे दर्ज करने के लिए संकेत देंगे। एक बार जब आप सही पासवर्ड प्रदान करते हैं, तो विभाजन सामान्य रूप से आगे बढ़ता है। यदि आपके पास पासवर्ड नहीं है, तो फ़ाइल को विभाजित नहीं किया जा सकता है, और प्राधिकरण के बिना पीडीएफ सुरक्षा को बायपास करने का प्रयास अधिकांश देशों में अवैध है।',
  'faq2-question' => 'क्या पीडीएफ को विभाजित करने से उसकी गुणवत्ता कम हो जाती है?',
  'faq2-answer' => 'नहीं, विभाजन पृष्ठों को दोबारा प्रस्तुत किए बिना निकालता है। आउटपुट पृष्ठों की सामग्री बाइट स्तर पर मूल के समान है। छवि गुणवत्ता, पाठ स्पष्टता और सभी स्वरूपण पूरी तरह से संरक्षित हैं।',
  'faq3-question' => 'क्या पीडीएफ़ को ऑनलाइन विभाजित करने के लिए कोई पृष्ठ सीमा है?',
  'faq3-answer' => 'सीमाएँ सेवा पर निर्भर करती हैं. PDFTools अपने निःशुल्क स्तर पर कई सौ पृष्ठों तक की फ़ाइलों को संभालता है। क्रोम या एक्रोबैट रीडर का उपयोग करने वाले ब्राउज़र-आधारित तरीकों के लिए, आपके कंप्यूटर की उपलब्ध मेमोरी से परे कोई पृष्ठ सीमा नहीं है।',
  'faq4-question' => 'क्या मैं पीडीएफ को स्वचालित रूप से अलग-अलग पृष्ठों में विभाजित कर सकता हूं?',
  'faq4-answer' => 'हाँ। पीडीएफटूल्स के ऑनलाइन टूल में प्रत्येक पृष्ठ को एक अलग फ़ाइल के रूप में निकालने का विकल्प शामिल है, जिससे एक ज़िप संग्रह तैयार किया जा सकता है जिसे आप डाउनलोड कर सकते हैं। पायथन स्क्रिप्ट विधि बड़े बैचों के लिए स्वचालित रूप से भी ऐसा कर सकती है।',
  'a' => 'पीडीएफ मर्ज करें',
  'method1-note2' => 'टूल आपको दस्तावेज़ संरचना पर पूर्ण नियंत्रण देने के लिए स्प्लिटर के साथ काम करता है।',
  'method4-note3' => 'तेज़ ब्राउज़र-आधारित समाधान के लिए PDFTools पर टूल।',
  'conclusion-para3' => 'औजार। परिणामी फ़ाइलों का आकार कम करने के लिए,',
  'a2' => 'पीडीएफ को संपीड़ित करें',
  'conclusion-para4' => 'टूल PDFTools पर निःशुल्क उपलब्ध है।',
);
